"""
    Question 5.2: Swap bits in a number
    """
def swap_bits(x: Any, j: Any, k: Any) -> object {
    if (((x >> j) & 1) != ((x >> k) & 1)) {
        mask = (1 << j) | (1 << k);
        x ^= mask;
    }
    return x;
}

